{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "UK-224,671, the highest-transfer analogue, had only 7.5% oral bioavailability in fasted humans, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Catechin showed approximately 1.68% oral bioavailability in humans, supporting very low systemic absorption for a polar polyphenol.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Epicatechin was reported to have low bioavailability, with most of the dose remaining unabsorbed in the intestine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "MK-458 had absolute oral bioavailability of approximately 5% in patients, clearly below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Rotigotine has low oral bioavailability in humans, limiting its clinical use.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Dihydrexidine exhibited low oral bioavailability in patients, consistent with poor absorption for a polar rigid amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Pethidine had approximately 56% oral bioavailability in healthy subjects, above the threshold, but it is a small lipophilic tertiary amine rather than a permanently charged quaternary ammonium.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer human oral bioavailability measurements for polar, poorly permeable analogues (UK-224,671, catechins, MK-458, rotigotine, dihydrexidine) are all below 20%. The query's permanent quaternary ammonium and multiple polar groups make poor absorption even more likely. The only high-F analogue, pethidine, is structurally distant and less transferable, so the overall prediction is low.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself is provided; the prediction relies on transferable analogues.",
    "The contradictory high-F evidence comes from a structurally distant tertiary amine opioid, limiting its transferability to the quaternary ammonium query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

